{
  "case_id": "C05",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "The problem",
      "narration": "Talking therapy is the recommended first treatment for long-term insomnia, but there are never enough therapists. So can an app do the job?",
      "on_screen": "Title: Can an app treat insomnia? Icon of a therapist's chair beside a phone.",
      "claim_refs": ["SYN-C05:background:cbt-first-line-access-limited"]
    },
    {
      "beat": "The trial",
      "narration": "Researchers randomly assigned 640 adults with chronic insomnia to a six-week CBT app or a sleep-hygiene app. Crucially, they registered two main questions in advance: does it ease insomnia symptoms, and does it improve daytime functioning?",
      "on_screen": "640 adults, split 1:1. Two labelled boxes: CO-PRIMARY 1 Insomnia severity (ISI); CO-PRIMARY 2 Daytime functioning (WSAS).",
      "claim_refs": ["SYN-C05:abstract:n640-rct-1to1", "SYN-C05:methods:two-co-primary-prespecified"]
    },
    {
      "beat": "Answer one: yes",
      "narration": "On symptoms, the app won clearly: insomnia scores fell 3.7 points further than the control, a solid, statistically strong result.",
      "on_screen": "ISI at week 8: difference 3.7 points, 95% CI 2.9 to 4.5, p<0.001.",
      "claim_refs": ["SYN-C05:results:isi-week8"]
    },
    {
      "beat": "Answer two: no",
      "narration": "On daytime functioning, it didn't. The difference was 0.2 points, and the uncertainty range straddles zero, so no benefit was shown.",
      "on_screen": "WSAS at week 8: difference 0.2 points, 95% CI -0.7 to 1.1, p=0.66.",
      "claim_refs": ["SYN-C05:results:wsas-week8"]
    },
    {
      "beat": "And it fades",
      "narration": "By six months the symptom advantage had shrunk to 1.9 points. All outcomes were self-reported, with no sleep monitoring.",
      "on_screen": "6 months: 3.7 down to 1.9 points. Note: self-report only, no actigraphy or polysomnography.",
      "claim_refs": ["SYN-C05:results:isi-6month", "SYN-C05:limitations:self-report-only"]
    },
    {
      "beat": "Bottom line",
      "narration": "So: the app helped people sleep better on paper, but this trial did not show it helped their days. Both answers were pre-registered, and both were reported.",
      "on_screen": "Symptoms: improved. Daily life: not shown. Both endpoints pre-registered and reported.",
      "claim_refs": ["SYN-C05:discussion:both-endpoints-reported"]
    }
  ]
}
